create table if not exists public.pricing_enquiries ( id uuid primary key default gen_random_uuid(), full_name text not null check (length(btrim(full_name)) between 1 and 120), email text not null check (position('@' in email) > 1 and length(email) <= 320), company text check (company is null or length(btrim(company)) between 1 and 160), budget_band text check (budget_band is null or length(budget_band) <= 40), interest text check (interest is null or length(interest) <= 40), message text not null check (length(btrim(message)) between 1 and 4000), source text not null default 'pricing-page' check (length(source) <= 40), status text not null default 'new' check (status in ('new', 'in-progress', 'closed', 'spam')), handled_by text, handled_at timestamptz, notes text check (notes is null or length(notes) <= 4000), created_at timestamptz not null default timezone('utc', now()) );
comment on table public.pricing_enquiries is 'Inbound requests for bulk, agency or negotiated pricing. Internal: a named person''s work address and what they say they can spend. No customer-facing policy.';
comment on column public.pricing_enquiries.budget_band is 'The label the form offered, not a number. A band is what somebody expects to spend, and converting it would invent precision.';
create index if not exists pricing_enquiries_status_created_idx on public.pricing_enquiries (status, created_at desc);
create index if not exists pricing_enquiries_created_idx on public.pricing_enquiries (created_at desc);
alter table public.pricing_enquiries enable row level security;
do $$ begin create policy "Admins manage pricing enquiries" on public.pricing_enquiries for all using (public.is_admin()) with check (public.is_admin()); exception when duplicate_object then null; end; $$;
